def classify_ttl(raw):
    ttl = inputs.get('ttl')
    if 'ttl' not in inputs:
        result = {'kind': 'missing', 'ttl': None}
    elif ttl is None:
        result = {'kind': 'null', 'ttl': None}
    elif type(ttl) is bool:
        result = {'kind': 'invalid', 'ttl': None}
    elif type(ttl) is int and 6 <= ttl <= 15:
        result = {'kind': 'integer', 'ttl': ttl}
    else:
        result = {'kind': 'invalid', 'ttl': None}
    return result
